987	+
988	+/// Drives `EntryDetailScreen` (spec-4-4) — the Boundaries' three-source
989	+/// composition, merged only here (AD-7: "it never imports/reaches into
990	+/// `MeusRegistrosCubit` or any other Cubit"):
991	+/// [SessionRepository.statusStream] (auth status — this cubit is the one
992	+/// documented compose point the Acceptance Criteria's third bullet names,
993	+/// even though nothing this screen renders branches on it today:
994	+/// `ExpiryOverlayHost`'s own independent subscription to the same stream,
995	+/// unchanged, is still what actually shows the session-expired overlay
996	+/// above this screen, Boundaries: "no new overlay"), [PendingEntryWrite
997	+/// Tracker.pendingWrites] feeding the one shared `deriveSyncBadgeState()`
998	+/// (never recomputed inline), and one [EntriesRepository.getById] fetch
999	+/// per [load] call.
1000	+///
1001	+/// A DI `factory` (Code Map) — unlike `MeusRegistrosCubit`'s
1002	+/// `lazySingleton`, a fresh instance per visit to `/meus-registros/:id`
1003	+/// matches this screen's single-fetch, throwaway lifecycle, mirroring the
1004	+/// capture cubits' own factory shape (`capture_injection.dart`).
1005	+class EntryDetailCubit extends Cubit<EntryDetailState> {
1006	+  EntryDetailCubit(this._repository, this._tracker, this._sessionRepository)
1007	+    : super(const EntryDetailLoading()) {
1008	+    _pendingSubscription = _tracker.pendingWrites.listen(
1009	+      (writes) => _pendingWrites = writes,
1010	+    );
1011	+    _sessionSubscription = _sessionRepository.statusStream.listen(
1012	+      (status) => _sessionStatus = status,
1013	+    );
1014	+  }
1015	+
1016	+  final EntriesRepository _repository;
1017	+  final PendingEntryWriteTracker _tracker;
1018	+  final SessionRepository _sessionRepository;
1019	+
1020	+  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
1021	+  late final StreamSubscription<SessionStatus> _sessionSubscription;
1022	+
1023	+  /// Mirrors `MeusRegistrosCubit`'s own field of the same name — the
1024	+  /// tracker's latest snapshot, read synchronously by [load]'s own badge
1025	+  /// derivation rather than awaiting a fresh stream value.
1026	+  List<PendingEntryWrite> _pendingWrites = const [];
1027	+
1028	+  /// The latest [SessionStatus] this cubit has observed off the composed
1029	+  /// [SessionRepository.statusStream] — exposed purely so a test can
1030	+  /// assert this cubit (not `EntryDetailScreen` itself) is the one
1031	+  /// composition point for auth status alongside Entry/badge data
1032	+  /// (Acceptance Criteria's third bullet, AD-7); never read by
1033	+  /// `EntryDetailScreen`, which renders only from [state].
1034	+  SessionStatus? get sessionStatus => _sessionStatus;
1035	+  SessionStatus? _sessionStatus;
1036	+
1037	+  /// Guards a stale in-flight [load] call's result landing after a newer
1038	+  /// one (e.g. a quick back-then-forward re-navigation) — same rationale
1039	+  /// and shape as `MeusRegistrosCubit._generation`.
1040	+  int _generation = 0;
1041	+
1042	+  /// `EntryDetailScreen`'s one driver, called from the `GoRoute.builder`
1043	+  /// cascade (Code Map: `sl<EntryDetailCubit>()..load(...)`) — [id] is
1044	+  /// either a real server id or a still-pending/failed placeholder's
1045	+  /// synthetic `tempId` (Boundaries: "un-special-cased navigation target");
1046	+  /// both are simply passed straight through to [EntriesRepository.
1047	+  /// getById] with no branching here.
1048	+  Future<void> load(String id) async {
1049	+    final generation = ++_generation;
1050	+    emit(const EntryDetailLoading());
1051	+    final result = await _repository.getById(id);
1052	+    if (isClosed || generation != _generation) {
1053	+      return;
1054	+    }
1055	+    result.match(
1056	+      (failure) {
1057	+        if (failure is NotFound) {
1058	+          emit(const EntryDetailNotFound());
1059	+          return;
1060	+        }
1061	+        // Boundaries: every other non-absorbed Failure renders the exact
1062	+        // same generic not-found treatment `EntryDetailScreen` gives
1063	+        // EntryDetailNotFound — kept as its own state only for a test's
1064	+        // sake (entry_detail_state.dart's own doc).
1065	+        emit(EntryDetailError(message: failure.message));
1066	+      },
1067	+      (entry) {
1068	+        PendingEntryWrite? matchingPending;
1069	+        for (final pending in _pendingWrites) {
1070	+          if (pending.tempId == entry.id) {
1071	+            matchingPending = pending;
1072	+            break;
1073	+          }
1074	+        }
1075	+        emit(
1076	+          EntryDetailData(
1077	+            entry: entry,
1078	+            badgeState: deriveSyncBadgeState(entry, matchingPending),
1079	+          ),
1080	+        );
1081	+      },
1082	+    );
1083	+  }
1084	+
1085	+  @override
1086	+  Future<void> close() async {
1087	+    await _pendingSubscription.cancel();
1088	+    await _sessionSubscription.cancel();
1089	+    return super.close();
1090	+  }
1091	+}
